  1	/**
  2	 * Dashboard View — Repo Parallelizer GUI.
  3	 *
  4	 * Renders the application's landing page: a list of all projects (with repo
  5	 * and workspace counts) and a "Create Project" quick-action form.
  6	 *
  7	 * @param {HTMLElement} container - The `#app` root element supplied by the router.
  8	 * @param {Object}      _params   - Route params (none for this route).
  9	 */
 10	
 11	import { api } from '../api.js';
 12	import { showToast } from '../components/toast.js';
 13	import { createFormField, validateRequired } from '../components/form-helpers.js';
 14	import { clearElement } from '../utils/dom.js';
 15	
 16	// ---------------------------------------------------------------------------
 17	// Debounce helper
 18	// ---------------------------------------------------------------------------
 19	
 20	/**
 21	 * Return a debounced version of `fn` that delays invocation by `wait` ms.
 22	 *
 23	 * @template {(...args: unknown[]) => void} T
 24	 * @param {T} fn
 25	 * @param {number} wait - Delay in milliseconds.
 26	 * @returns {T}
 27	 */
 28	function debounce(fn, wait) {
 29	    let timer;
 30	    return function (...args) {
 31	        clearTimeout(timer);
 32	        timer = setTimeout(() => fn.apply(this, args), wait);
 33	    };
 34	}
 35	
 36	// ---------------------------------------------------------------------------
 37	// Router instance — imported lazily to avoid circular-dependency issues.
 38	// app.js sets this via setRouter() immediately after instantiation.
 39	// ---------------------------------------------------------------------------
 40	
 41	/** @type {import('../router.js').Router|null} */
 42	let _router = null;
 43	
 44	/**
 45	 * Inject the router instance so the dashboard can call `router.navigate()`.
 46	 * Called from app.js before the router starts.
 47	 *
 48	 * @param {import('../router.js').Router} router
 49	 */
 50	export function setRouter(router) {
 51	    _router = router;
 52	}
 53	
 54	// ---------------------------------------------------------------------------
 55	// Internal helpers
 56	// ---------------------------------------------------------------------------
 57	
 58	/**
 59	 * Build a single project card DOM element.
 60	 *
 61	 * @param {{ id?: string, Id?: string, Name?: string, name?: string,
 62	 *           Description?: string, description?: string,
 63	 *           Repositories?: Array }} project
 64	 * @param {number} workspaceCount
 65	 * @returns {HTMLElement}
 66	 */
 67	function buildProjectCard(project, workspaceCount) {
 68	    // The backend may use either capitalised or lowercase keys — normalise.
 69	    const id          = project.Id          || project.id          || '';
 70	    const name        = project.Name        || project.name        || id;
 71	    const description = project.Description || project.description || '';
 72	    const repoCount   = Array.isArray(project.Repositories)
 73	        ? project.Repositories.length
 74	        : (Array.isArray(project.repositories) ? project.repositories.length : 0);
 75	
 76	    const card = document.createElement('div');
 77	    card.className = 'card project-card';
 78	
 79	    // Header row: name + navigate link
 80	    const header = document.createElement('div');
 81	    header.className = 'card-header';
 82	
 83	    const titleLink = document.createElement('a');
 84	    titleLink.className = 'project-card-title';
 85	    titleLink.href = `#/projects/${encodeURIComponent(id)}`;
 86	    titleLink.textContent = name;
 87	    titleLink.addEventListener('click', (e) => {
 88	        e.preventDefault();
 89	        if (_router) {
 90	            _router.navigate(`#/projects/${encodeURIComponent(id)}`);
 91	        }
 92	    });
 93	
 94	    const projectId = document.createElement('span');
 95	    projectId.className = 'project-card-id text-muted';
 96	    projectId.textContent = id;
 97	
 98	    header.appendChild(titleLink);
 99	    header.appendChild(projectId);
100	    card.appendChild(header);

101	
102	    // Optional description
103	    if (description) {
104	        const desc = document.createElement('p');
105	        desc.className = 'project-card-description text-secondary';
106	        desc.textContent = description;
107	        card.appendChild(desc);
108	    }
109	
110	    // Stats row
111	    const stats = document.createElement('div');
112	    stats.className = 'project-card-stats';
113	
114	    const repoStat = document.createElement('span');
115	    repoStat.className = 'stat-chip';
116	    repoStat.textContent = `${repoCount} ${repoCount === 1 ? 'repository' : 'repositories'}`;
117	
118	    const wsStat = document.createElement('span');
119	    wsStat.className = 'stat-chip';
120	    wsStat.textContent = `${workspaceCount} ${workspaceCount === 1 ? 'workspace' : 'workspaces'}`;
121	
122	    const separator = document.createElement('span');
123	    separator.className = 'stat-separator';
124	    separator.textContent = '·';
125	
126	    stats.appendChild(repoStat);
127	    stats.appendChild(separator);
128	    stats.appendChild(wsStat);
129	    card.appendChild(stats);
130	
131	    return card;
132	}
133	
134	/**
135	 * Render a loading skeleton inside a container element.
136	 *
137	 * @param {HTMLElement} el
138	 */
139	function showLoading(el) {
140	    el.innerHTML = `
141	        <div class="loading-indicator" aria-live="polite" aria-label="Loading projects…">
142	            <span class="spinner" aria-hidden="true"></span>
143	            <span>Loading projects…</span>
144	        </div>
145	    `;
146	}
147	
148	// ---------------------------------------------------------------------------
149	// Filter / Sort toolbar
150	// ---------------------------------------------------------------------------
151	
152	/**
153	 * Represents the current filter and sort state for the project list toolbar.
154	 *
155	 * This object flows between {@link renderDashboard}, {@link buildFilterToolbar},
156	 * and (in a future work package) the filter/sort logic inside `renderProjectList`.
157	 *
158	 * @typedef {Object} FilterState
159	 * @property {string} search - Free-text search query matched against project names
160	 *   and descriptions. Empty string means "no search filter applied".
161	 * @property {string} repoId - ID of the repository to filter by, or `''` to show
162	 *   projects from all repositories ("All repositories" option). Matches `repo.id`
163	 *   / `repo.Id` values returned by `api.repositories.list()`.
164	 * @property {'alpha'|'activity'} sort - Sort order for the project list.
165	 *   - `'alpha'`    — alphabetical by project name (A → Z). This is the default.
166	 *   - `'activity'` — most recently active project first (Last Activity order).
167	 *
168	 * @example
169	 * // Default state — no filter, alphabetical sort
170	 * const filterState = { search: '', repoId: '', sort: 'alpha' };
171	 *
172	 * @example
173	 * // Filter to a specific repo, sorted by last activity
174	 * const filterState = { search: 'api', repoId: 'backend-repo', sort: 'activity' };
175	 */
176	
177	/**
178	 * Build the filter/sort toolbar for the project list.
179	 *
180	 * Fetches `api.repositories.list()` to populate the repository dropdown.
181	 * If the fetch fails the toolbar renders without the repository dropdown and
182	 * shows a toast error.
183	 *
184	 * @param {FilterState} initialState      - The current filter/sort values.
185	 * @param {function(FilterState): void} onFilterChange - Callback fired when any
186	 *   control value changes.
187	 * @returns {Promise<HTMLElement>}
188	 */
189	async function buildFilterToolbar(initialState, onFilterChange) {
190	    const bar = document.createElement('div');
191	    bar.className = 'project-filter-toolbar';
192	
193	    // ---- Current state (mutated as controls change) ----
194	    const state = { ...initialState };
195	
196	    // ---- Helper: notify caller ----
197	    const notify = () => onFilterChange({ ...state });
198	
199	    // ---- Search input ----
200	    const searchInput = document.createElement('input');
201	    searchInput.type        = 'search';
202	    searchInput.className   = 'form-input project-filter-search';
203	    searchInput.placeholder = 'Search projects\u2026';
204	    searchInput.value       = state.search;
205	    searchInput.setAttribute('aria-label', 'Search projects');
206	
207	    const debouncedSearch = debounce(() => {
208	        state.search = searchInput.value;
209	        notify();
210	    }, 250);
211	    searchInput.addEventListener('input', debouncedSearch);
212	
213	    bar.appendChild(searchInput);
214	
215	    // ---- Repository filter dropdown ----
216	    let repos = [];
217	    try {
218	        repos = await api.repositories.list();
219	    } catch (err) {
220	        showToast(err.message || 'Failed to load repositories for filter.', 'error');
221	    }
222	
223	    if (Array.isArray(repos) && repos.length > 0) {
224	        const repoSelect = document.createElement('select');
225	        repoSelect.className = 'form-select project-filter-repo';
226	        repoSelect.setAttribute('aria-label', 'Filter by repository');
227	
228	        const allOpt = document.createElement('option');
229	        allOpt.value       = '';
230	        allOpt.textContent = 'All repositories';
231	        repoSelect.appendChild(allOpt);
232	
233	        repos.forEach((repo) => {
234	            const opt = document.createElement('option');
235	            opt.value       = repo.id || repo.Id || '';
236	            opt.textContent = repo.name || repo.Name || opt.value;
237	            if (opt.value === state.repoId) opt.selected = true;
238	            repoSelect.appendChild(opt);
239	        });
240	
241	        repoSelect.addEventListener('change', () => {
242	            state.repoId = repoSelect.value;
243	            notify();
244	        });
245	
246	        bar.appendChild(repoSelect);
247	    }
248	
249	    // ---- Sort selector ----
250	    const sortSelect = document.createElement('select');

100	
101	api.repositories.list = async () => [REPO_A, REPO_B];
