398	/**
399	 * Module-level cache of fully-enriched project detail objects.
400	 * Each entry is `{ fullProject, wsCount }` as returned by the API fetch.
401	 * Populated by `renderProjectList()` and consumed by `applyFiltersAndSort()`.
402	 *
403	 * @type {Array<{ fullProject: Object, wsCount: number }>}
404	 */
405	let _allProjects = [];
406	
407	// ---------------------------------------------------------------------------
408	// Filter / sort logic
409	// ---------------------------------------------------------------------------
410	
411	/**
412	 * Apply the current filter/sort state to `_allProjects` and return the
413	 * matching subset in the requested order.
414	 *
415	 * Filter rules (all applied together — AND semantics):
416	 *   - `search`  — case-insensitive substring match against name, ID, and
417	 *                 description. Empty string means no filter.
418	 *   - `repoId`  — project must contain a repository whose `id`/`Id` equals
419	 *                 `repoId`. Empty string means no filter.
420	 *
421	 * Sort rules:
422	 *   - `'alpha'`    — ascending by name (case-insensitive); tiebreaker: project
423	 *                    ID ascending.
424	 *   - `'activity'` — descending by `LastActivity` / `lastActivity`; entries
425	 *                    with `null`/`undefined` activity sort last; tiebreaker:
426	 *                    name ascending (case-insensitive).
427	 *
428	 * @param {FilterState} filterState
429	 * @returns {Array<{ fullProject: Object, wsCount: number }>}
430	 */
431	function applyFiltersAndSort(filterState) {
432	    const { search, repoId, sort } = filterState;
433	    const needle = search.trim().toLowerCase();
434	
435	    let result = _allProjects.filter(({ fullProject }) => {
436	        const id   = (fullProject.Id   || fullProject.id          || '').toLowerCase();
437	        const name = (fullProject.Name || fullProject.name        || '').toLowerCase();
438	        const desc = (fullProject.Description || fullProject.description || '').toLowerCase();
439	
440	        // Search filter — substring match across name, ID, description.
441	        if (needle && !name.includes(needle) && !id.includes(needle) && !desc.includes(needle)) {
442	            return false;
443	        }
444	
445	        // Repository filter — project must contain the selected repo.
446	        if (repoId) {
447	            const repos = Array.isArray(fullProject.Repositories)
448	                ? fullProject.Repositories
449	                : (Array.isArray(fullProject.repositories) ? fullProject.repositories : []);
450	            const hasRepo = repos.some((r) => (r.id || r.Id || '') === repoId);

250	        assert.ok(names.includes('Alpha Project'), `"Alpha Project" should be visible`);
251	        assert.ok(names.includes('Beta Project'),  `"Beta Project" should be visible`);
252	        assert.ok(!names.includes('Zeta Search'),  `"Zeta Search" should be hidden`);
253	    } finally {
254	        cleanup();
255	    }
256	});
