510	 * `_allProjects` is non-empty (i.e. filters excluded everything).
511	 * Shows the original "No projects yet." message when there are no projects at all.
512	 * Otherwise renders the project cards inside a `.project-grid` wrapper.
513	 *
514	 * @param {HTMLElement}                                  listContainer
515	 * @param {Array<{ fullProject: Object, wsCount: number }>} filtered
516	 */
517	function renderProjectGrid(listContainer, filtered) {
518	    clearElement(listContainer);
519	
520	    if (filtered.length === 0) {
521	        const empty = document.createElement('div');
522	        empty.className = 'empty-state';
523	        if (_allProjects.length === 0) {
524	            empty.textContent = 'No projects yet. Use the "Create Project" button to add one.';
525	        } else {
526	            empty.textContent = 'No projects match the current filters.';
527	        }
528	        listContainer.appendChild(empty);
529	        return;
530	    }
531	
532	    const grid = document.createElement('div');
533	    grid.className = 'project-grid';
534	
535	    filtered.forEach(({ fullProject, wsCount }) => {
536	        grid.appendChild(buildProjectCard(fullProject, wsCount));
537	    });
538	
539	    listContainer.appendChild(grid);
540	}
541	
542	// ---------------------------------------------------------------------------
543	// Project list — fetch + render
544	// ---------------------------------------------------------------------------
545	
546	/**
547	 * Fetch all project data from the API, update `_allProjects`, then apply
548	 * the current `filterState` and render the result into `listContainer`.
549	 *
550	 * Workspace counts are fetched in parallel for each project.  If a workspace
551	 * fetch fails the count is shown as "0 workspaces" rather than breaking the
552	 * whole list.
553	 *
554	 * @param {HTMLElement} listContainer - Element to render the list into.
555	 * @param {FilterState} filterState   - Current filter/sort state to apply
556	 *   after the data is loaded.
557	 */
558	async function renderProjectList(listContainer, filterState) {
559	    showLoading(listContainer);
560	
561	    let projects;
562	    try {
563	        projects = await api.projects.list();
564	    } catch (err) {
565	        clearElement(listContainer);
566	        const errMsg = document.createElement('div');
567	        errMsg.className = 'empty-state error-state';
568	        errMsg.textContent = `Failed to load projects: ${err.message}`;
569	        listContainer.appendChild(errMsg);
570	        showToast(err.message || 'Failed to load projects.', 'error');
571	        return;
572	    }
573	
574	    if (!Array.isArray(projects) || projects.length === 0) {
575	        _allProjects = [];
576	        renderProjectGrid(listContainer, []);
577	        return;
578	    }
579	
580	    // Fetch full project data + workspace counts in parallel per project.
581	    const projectDetails = await Promise.all(
582	        projects.map(async (project) => {
583	            const id = project.Id || project.id || '';
584	            let fullProject = project;
585	            let wsCount = 0;
586	            try {
587	                const [full, workspaces] = await Promise.all([
588	                    api.projects.get(id),
589	                    api.workspaces.list(id),
590	                ]);
591	                fullProject = full;
592	                wsCount = Array.isArray(workspaces) ? workspaces.length : 0;
593	            } catch (_err) {
594	                // Degrade gracefully — show index data with 0 counts.
595	            }
596	            return { fullProject, wsCount };
597	        }),
598	    );
599	
600	    _allProjects = projectDetails;
601	
602	    const filtered = applyFiltersAndSort(filterState);
603	    renderProjectGrid(listContainer, filtered);
604	}
605	
606	// ---------------------------------------------------------------------------
607	// Public export — view function
608	// ---------------------------------------------------------------------------
609	
610	/**
611	 * Render the dashboard view.
612	 *
613	 * @param {HTMLElement} container - The `#app` root element.
614	 * @param {Object}      _params   - Route params (unused).
615	 */
616	export async function renderDashboard(container, _params) {
617	    // -----------------------------------------------------------------------
618	    // Page header
619	    // -----------------------------------------------------------------------
620	    const header = document.createElement('div');
621	    header.className = 'page-header';
622	
623	    const title = document.createElement('h1');
624	    title.textContent = 'Projects';
625	    header.appendChild(title);
626	
627	    container.appendChild(header);
628	
629	    // -----------------------------------------------------------------------
630	    // Project list section (declared early so onFilterChange can reference it)
631	    // -----------------------------------------------------------------------
632	    const listContainer = document.createElement('div');
633	    listContainer.className = 'project-list-container';
634	
635	    // -----------------------------------------------------------------------
636	    // Filter / sort toolbar (inserted between header and project list)
637	    // -----------------------------------------------------------------------
638	
639	    /** @type {FilterState} */
640	    const filterState = { search: '', repoId: '', sort: 'alpha' };
641	
642	    /**
643	     * Called whenever a toolbar control changes.  Applies the updated
644	     * filter/sort state to the cached project data without re-fetching.
645	     *
646	     * @param {FilterState} newState
647	     */
648	    const onFilterChange = (newState) => {
649	        Object.assign(filterState, newState);
650	        const filtered = applyFiltersAndSort(filterState);

651	        renderProjectGrid(listContainer, filtered);
652	    };
653	
654	    const toolbar = await buildFilterToolbar(filterState, onFilterChange);
655	    container.appendChild(toolbar);
656	
657	    // Insert list container after toolbar
658	    container.appendChild(listContainer);
659	
660	    // -----------------------------------------------------------------------
661	    // Create Project section
662	    // -----------------------------------------------------------------------
663	    const createSection = buildCreateProjectSection(() => {
664	        // Re-fetch all project data from the API and re-apply the current
665	        // filter/sort state so newly created projects appear immediately.
666	        renderProjectList(listContainer, filterState);
667	    });
668	    container.appendChild(createSection);
669	
670	    // -----------------------------------------------------------------------
671	    // Initial load
672	    // -----------------------------------------------------------------------
673	    await renderProjectList(listContainer, filterState);
674	}

